A simple observation is that for any $\Pi \in \mc{P}_{n,k}$ and any $v \in \mathbb{R}^n$, it holds that  egin{equation*} 
norm{\Pi v - \Pi^{*\T} v}_0 = 
norm{(\Pi - I_n) v - (\Pi^{*\T} - I_n) v}_0 \leq 
norm{(\Pi - I_n) v}_0 + 
norm{(\Pi^{*\T} - I_n) v}_0 \leq 2k. \end{equation*}

Consider optimization problem \eqref{eq:lsq} and for positive integers $m$, denote $
u_m = \E_{g \sim N(0, I_m)}[
norm{g}_2] \in \left[ rac{m}{(m+1)^{1/2}}, \; m^{1/2} ight]$ and let $\varepsilon \in (0,1/2)$ be a number such that  egin{equation} 
u_{n-d} -  rac{\varepsilon}{1-\varepsilon}
u_n \geq  rac{2}{1 - \varepsilon} w(\mc{T}). \end{equation} If furthermore $n > 9 \vee 4d$, then with probability $\geq 1 -  rac{7}{2}\exp(-c_{\varepsilon} n) - 2 \exp \left(- rac{1}{2} (d \vee \log n) ight)$,  egin{equation} 
norm{\wh{ eta} -  eta^*}_2 \leq  rac{\sigma}{1 - \sqrt{ rac{4 d \vee \log n}{n}}} \left(\sqrt{ rac{5 (d \vee \log n)}{n}} +  rac{2 (1 + \sqrt{2}) \varepsilon^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}} ight). \end{equation}

For $b \in \mathbb{R}^d$, consider $\wh{\Pi}(b) = \argmax_{\Pi \in \mc{P}_n} \scp{\Pi X b}{\mathbf{y}}$.  egin{itemize} \item[(a)] Let $\delta, \Delta, \eta > 0$, and let $\wh{	heta}$ be an estimator s.t.~the event $\{
norm{X \wh{	heta} - X eta^*}_{\infty} \leq \sigma \Delta \}$ holds with probability at least $1 - \eta$. If  egin{equation*} \dfrac{\| eta^*\|_2^2}{\sigma^2}>\dfrac{n^2(n-1)^2}{4 \delta^2\pi} \left( \Delta + 2 \log\dfrac{n(n-1)}{\delta} ight)^2, \: \: 	ext{then} \: \: \p(\widehat{\Pi}(\wh{	heta}) 
e \Pi^*)\le 2\delta + \eta. \end{equation*} \item[(b)] Suppose that $n \geq 5$. If  egin{equation*} \dfrac{\| eta^*\|_2^2}{\sigma^2}< C n^2, \: \: 	ext{for some constant $C>0$, then} \: \: \p(\widehat{\Pi}( eta^*)
e \Pi^*)\ge .35. \end{equation*} \end{itemize}

Using standard concentration arguments, one shows that  egin{equation*} 
norm{X \wh{	heta} - X eta^*}_{\infty} \leq \max_{1 \leq i \leq n} 
norm{\mathbf{x}_i}_2 
norm{\wh{	heta} -  eta^*}_2 \leq C (\sqrt{d} + \sqrt{\log n}) 
norm{\wh{	heta} -  eta^*}_2 \end{equation*} holds with high probability.

Consider the least squares problem \eqref{eq:lsq} with $\mathbf{y} =  oldsymbol{\epsilon}$:  egin{equation*} \min_{\Pi,  eta} 
norm{ oldsymbol{\epsilon} - \Pi X  eta}_2^2. \end{equation*} Omitting the term not depending on $ eta$, an equivalent problem is given by  egin{equation*} \min_{\Pi,  eta} -2 \scp{\Pi  oldsymbol{\epsilon}}{X  eta} + 
norm{X  eta}_2^2. \end{equation*} Re-parameterizing $X  eta = u \cdot r$, with $r \geq 0$ for $u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}$, we obtain the optimization problem  egin{equation*} \min_{\Pi, u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}, r \geq 0} -2 \scp{\Pi  oldsymbol{\epsilon}}{u} r + r^2. \end{equation*} Observe that for any $u$ and $\Pi$, the optimal value of $r$ is found as  egin{equation*} \wh{r}(u) = \max\{\scp{\Pi  oldsymbol{\epsilon}}{u},0 \}. \end{equation*} In particular, for a minimizer $(\wh{\Pi}, \wh{u})$,  egin{equation*} \wh{r} \coloneq \wh{r}(\wh{\Pi}, \wh{u}) = 
scp{\wh{\Pi}  oldsymbol{\epsilon}}{\wh{u}} \end{equation*} so that $\wh{r} = 
norm{X \wh{ eta}}_2$, and the optimal value of the objective is given by $-\wh{r}^2$. We hence have  egin{align*} \wh{r} &= \max_{u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}, \Pi} 
scp{\Pi  oldsymbol{\epsilon}}{u} \ &\geq \max_{1 \leq j \leq d, \Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_j / 
norm{X_j}_2} \ &\geq \max_{\Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_1}  rac{1}{
norm{X_1}_2}. \end{align*} We now bound  egin{equation*} \max_{\Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_1} \geq 
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1}, \end{equation*} where the permutation $\Pi_{\pm}$ is defined as follows. Define  egin{align*} n_{ oldsymbol{\epsilon},+} = \{i:\; \epsilon_i > 0\}, \quad n_{ oldsymbol{\epsilon},-} = n - n_{ oldsymbol{\epsilon},+}, \quad n_{X_1,+} = \{i:\; X_{i1} > 0\}, \quad n_{X_1,-} = n - n_{X_1,+}. \end{align*} Let further  egin{equation} n_+ = \min\{n_{ oldsymbol{\epsilon},+}, n_{X_1,+} \}, \quad n_- = \min\{n_{ oldsymbol{\epsilon},-}, n_{X_1,-} \}, \quad n_{\pm} = n - n_+ - n_-. \end{equation} Denote by  egin{alignat*}{2} &i_1^+ < \ldots < i_{n_{X,+}}^+ \quad &&	ext{the indices of the positive entries of $X_1$},\ &j_1^+ < \ldots < j_{n_{ oldsymbol{\epsilon},+}}^+ \quad &&	ext{the indices of the positive entries of $ oldsymbol{\epsilon}$},\ &i_1^- < \ldots < i_{n_{X,-}}^- \quad &&	ext{the indices of the negative entries of $X_1$},\ &j_1^- < \ldots < j_{n_{ oldsymbol{\epsilon},-}}^- \quad &&	ext{the indices of the negative entries of $ oldsymbol{\epsilon}$}. \end{alignat*} Furthermore, let  egin{align*} &i_{1}^{\pm} < \ldots < i_{n_{\pm}}^{\pm} \ &j_{1}^{\pm} < \ldots < j_{n_{\pm}}^{\pm} \end{align*} be the indices in  egin{align*} & \{1,\ldots,n\} \setminus (\{i_1^+,\ldots, i_{n_+}^+\} \cup \{i_1^-,\ldots, i_{n_-}^-\}) \ 	ext{respectively}\;\, & \{1,\ldots,n\} \setminus (\{j_1^+,\ldots, j_{n_+}^+\} \cup \{j_1^-,\ldots, j_{n_-}^-\}) \end{align*} in increasing order. We then construct $\Pi_{\pm}$ such that  egin{equation*} 
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1} = \sum_{k = 1}^{n_+} X_{1{i_k^+}} \epsilon_{j_k^+} + \sum_{k = 1}^{n_-} X_{1{i_k^-}} \epsilon_{j_k^-} + \sum_{k = 1}^{n_{\pm}} X_{1{i_k}^{\pm}} \; \epsilon_{{j_k}^{\pm}}. \end{equation*} All terms inside the first two sums are i.i.d.~from the same distribution as $|g| |h|$, where $g$ and $h$ are independent $N(0,1)$-random variables, and accordingly the terms inside the last summand are i.i.d.~from the same distribution as $-|g||h|$. Conditional on $n_{\pm}$, hence $
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1}$ follows the same distribution as  egin{equation*} \sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i| - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i|, \end{equation*} where $\{ g_i \}_{i = 1}^n$ and $\{ h_i \}_{i = 1}^n$ are two independent sequences of $n$ i.i.d.~random variables from the $N(0,1)$-distribution. The expectation of the above expression (conditional on $n_{\pm}$) is given by  egin{equation*} (n - 2 n_{\pm}) \E[|g||h|] = (n - 2 n_{\pm}) \E[|g|]^2 = (n - 2 n_{\pm})  rac{2}{\pi}. \end{equation*} From Proposition 5.16 in \cite{Vershynin2010}, we have the following concentration inequality:  egin{equation*} \p \left(\left|\sum_{i = 1}^{n - n_{\pm}} (|g_i| |h_i| - \E[|g||h|]) - \sum_{i=n - n_{\pm} + 1}^{n} (|g_i| |h_i| - \E[|g||h|]) ight| \geq (n - 2 n_{\pm})  rac{1}{\pi} \Big| n_{\pm} ight) \leq \exp(-n c). \end{equation*} Hence, conditional on $n_{\pm}$, with probability at least $1 - \exp(-nc)$,  egin{equation*} \sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i| - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i| \geq  rac{1}{\pi} (n - 2 n_{\pm}). \end{equation*} Consider the definition of $n_+$ and $n_-$ Observe that $n_{ oldsymbol{\epsilon}, +}$, $n_{X_1, +}$, $n_{ oldsymbol{\epsilon}, -}$ and $n_{X_1, -}$ are each binomial random variables with $n$ trials and probability of success $1/2$. By repeated application of Hoeffding's inequality, we hence have  egin{equation*} \p(n_{+} \leq 3n/8) \leq 2\exp(-n/32), \quad \p(n_{-} \leq 3n/8) \leq 2 \exp(-n/32). \end{equation*} Conditional on the events $\{ n_{+} > 3n/8\}$ and $\{ n_{-} > 3n/8\}$, we have $n_{\pm} \leq 1/4$ and thus with probability at least $1 - C \exp(-nc)$  egin{equation*} \sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i| - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i| \geq  rac{n}{2\pi} . \end{equation*} Accordingly, the same applies to the event $\{ 
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1} >  rac{n}{2\pi} \}$. Lemma ef{lem:normconcentration} in Appendix ef{app:aux} yields $
norm{X_1}_2 \leq 2 \sqrt{n}$ with probability at least $1 - \exp(-n/2)$. Putting together the pieces, it follows that with probability at least $1 - C \exp(-nc)$  egin{equation*} 
norm{X \wh{ eta}}_2 = \wh{r} \geq  rac{\sqrt{n}}{4\pi} \quad \Rightarrow \; 
norm{\wh{ eta}}_2 \geq  rac{\sqrt{n}}{\sigma_{\max}(X) 4\pi}, \end{equation*} where $\sigma_{\max}(X)$ denotes the maximum singular value of $X$. Finally, Lemma ef{lem:extremesingularvalues} in Appendix ef{app:aux} yields that $\sigma_{\max}(X) \leq \sqrt{2n} + \sqrt{d}$ with probability at least $1 - \exp(-c n)$, which concludes the proof.

Re-parameterizing $X  eta = u \cdot r$, with $r \geq 0$ for $u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}$, we obtain the optimization problem  egin{equation*} \min_{\Pi, u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}, r \geq 0} -2 \scp{\Pi  oldsymbol{\epsilon}}{u} r + r^2. \end{equation*} Observe that for any $u$ and $\Pi$, the optimal value of $r$ is found as  egin{equation*} \wh{r}(u) = \max\{\scp{\Pi  oldsymbol{\epsilon}}{u},0 \}. \end{equation*} In particular, for a minimizer $(\wh{\Pi}, \wh{u})$,  egin{equation*} \wh{r} \coloneq \wh{r}(\wh{\Pi}, \wh{u}) = 
scp{\wh{\Pi}  oldsymbol{\epsilon}}{\wh{u}} \end{equation*} so that $\wh{r} = 
norm{X \wh{ eta}}_2$, and the optimal value of the objective is given by $-\wh{r}^2$. We hence have  egin{align*} \wh{r} &= \max_{u \in 	ext{range}(X) \cap \mathbb{S}^{n-1}, \Pi} 
scp{\Pi  oldsymbol{\epsilon}}{u} \ &\geq \max_{1 \leq j \leq d, \Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_j / 
norm{X_j}_2} \ &\geq \max_{\Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_1}  rac{1}{
norm{X_1}_2}. \end{align*}

We now bound  egin{equation*} \max_{\Pi} 
scp{\Pi  oldsymbol{\epsilon}}{X_1} \geq 
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1}, \end{equation*} where the permutation $\Pi_{\pm}$ is defined as follows. Define  egin{align*} n_{ oldsymbol{\epsilon},+} = \{i:\; \epsilon_i > 0\}, \quad n_{ oldsymbol{\epsilon},-} = n - n_{ oldsymbol{\epsilon},+}, \quad n_{X_1,+} = \{i:\; X_{i1} > 0\}, \quad n_{X_1,-} = n - n_{X_1,+}. \end{align*} Let further  egin{equation} n_+ = \min\{n_{ oldsymbol{\epsilon},+}, n_{X_1,+} \}, \quad n_- = \min\{n_{ oldsymbol{\epsilon},-}, n_{X_1,-} \}, \quad n_{\pm} = n - n_+ - n_-. \end{equation} Denote by  egin{alignat*}{2} &i_1^+ < \ldots < i_{n_{X,+}}^+ \quad &&	ext{the indices of the positive entries of $X_1$},\ &j_1^+ < \ldots < j_{n_{ oldsymbol{\epsilon},+}}^+ \quad &&	ext{the indices of the positive entries of $ oldsymbol{\epsilon}$},\ &i_1^- < \ldots < i_{n_{X,-}}^- \quad &&	ext{the indices of the negative entries of $X_1$},\ &j_1^- < \ldots < j_{n_{ oldsymbol{\epsilon},-}}^- \quad &&	ext{the indices of the negative entries of $ oldsymbol{\epsilon}$}. \end{alignat*} Furthermore, let  egin{align*} &i_{1}^{\pm} < \ldots < i_{n_{\pm}}^{\pm} \ &j_{1}^{\pm} < \ldots < j_{n_{\pm}}^{\pm} \end{align*} be the indices in  egin{align*} & \{1,\ldots,n\} \setminus (\{i_1^+,\ldots, i_{n_+}^+\} \cup \{i_1^-,\ldots, i_{n_-}^-\}) \ 	ext{respectively}\;\, & \{1,\ldots,n\} \setminus (\{j_1^+,\ldots, j_{n_+}^+\} \cup \{j_1^-,\ldots, j_{n_-}^-\}) \end{align*} in increasing order. We then construct $\Pi_{\pm}$ such that  egin{equation*} 
scp{\Pi_{\pm}  oldsymbol{\epsilon}}{X_1} = \sum_{k = 1}^{n_+} X_{1{i_k^+}} \epsilon_{j_k^+} + \sum_{k = 1}^{n_-} X_{1{i_k^-}} \epsilon_{j_k^-} + \sum_{k = 1}^{n_{\pm}} X_{1{i_k}^{\pm}} \; \epsilon_{{j_k}^{\pm}}. \end{equation*}

Lemma ef{lem:normconcentration} in Appendix ef{app:aux} yields $
norm{X_1}_2 \leq 2 \sqrt{n}$ with probability at least $1 - \exp(-n/2)$. Putting together the pieces, it follows that with probability at least $1 - C \exp(-nc)$  egin{equation*} 
norm{X \wh{ eta}}_2 = \wh{r} \geq  rac{\sqrt{n}}{4\pi} \quad \Rightarrow \; 
norm{\wh{ eta}}_2 \geq  rac{\sqrt{n}}{\sigma_{\max}(X) 4\pi}, \end{equation*} where $\sigma_{\max}(X)$ denotes the maximum singular value of $X$. Finally, Lemma ef{lem:extremesingularvalues} in Appendix ef{app:aux} yields that $\sigma_{\max}(X) \leq \sqrt{2n} + \sqrt{d}$ with probability at least $1 - \exp(-c n)$, which concludes the proof.

We start with a basic, yet important observation that allows us to decouple $\wh{\Pi}$ and $\wh{ eta}$. Let $	exttt{P}_X$ and $	exttt{P}_X^{\perp}$ denote the orthogonal projection on $	ext{range}(X)$ respectively its orthogonal complement.  egin{lemma} Consider optimization problem \eqref{eq:lsq}. Then, if $n \geq d$, with probability one  egin{equation} \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} 
norm{\emph{	exttt{P}}_X^{\perp} \Pi \mathbf{y}}_2^2, \qquad \wh{ eta} \in \left\{ \left( rac{X^{\T} X}{n} ight)^{-1}  rac{X^{\T} \wh{\Pi}^{\T} \mathbf{y}}{n}, \; \, \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} 
norm{\emph{	exttt{P}}_X^{\perp} \Pi \mathbf{y}}_2^2 ight \}. \end{equation} \end{lemma}  egin{proof} We have  egin{align*} \min_{\Pi,  eta} \|\Pi X eta-\mathbf{y}\|_2^2 &= \min_{\Pi,  eta} \|X eta-\Pi \mathbf{y}\|_2^2 \ &= \min_{\Pi,  eta} \left\{ \|	exttt{P}_X^{\perp} \Pi \mathbf{y}\|_2^2 + \|X eta- 	exttt{P}_X \Pi \mathbf{y}\|_2^2 ight\}. \end{align*} The second part can always be made equal to zero by choosing $ eta$ such that $X  eta = 	exttt{P}_X \Pi \mathbf{y}$. It hence suffices to minimize the first part w.r.t.~$\Pi$ and to back-substitute the result into the second part. Under model (	ext{	extbf{G}}), $X$ is non-singular with probability one as long as $n \geq d$ which yields the second expression in \eqref{eq:decomposition}. \end{proof} 
