scp{	exttt{P}_X^{\perp}\Pi^{*\T} \mathbf{y}}{(\wh{\Pi}^{\T} - \Pi^{*\T}) \mathbf{y}}|. \end{align*} Since  egin{equation*} 	exttt{P}_X^{\perp} \Pi^{*\T} \mathbf{y} = 	exttt{P}_X^{\perp} (X  eta^* +  oldsymbol{\epsilon}) = 	exttt{P}_X^{\perp} oldsymbol{\epsilon}, \end{equation*} we have the implication that  egin{equation*} 
norm{	exttt{P}_X^{\perp}(\wh{\Pi}^{\T} - \Pi^{*\T}) \mathbf{y}}_2^2 \leq 2 |
scp{	exttt{P}_X^{\perp} oldsymbol{\epsilon}}{(\wh{\Pi}^{\T} - \Pi^{*\T}) \mathbf{y}}|. \end{equation*} Dividing both sides by $
norm{	exttt{P}_X^{\perp}(\wh{\Pi}^{\T} - \Pi^{*\T}) \mathbf{y}}_2$, we obtain that  egin{align} &
norm{(\wh{\Pi}^{\T} - \Pi^{*\T}) \mathbf{y}}_2^2 
